  "judul": "PERANCANGAN GAME 2D FIGHTING TENTANG TOKOH MITOLOGI NUSANTARA UNTUK PENGENALAN BUDAYA DI KALANGAN REMAJA",
  "semester": "Genap 2024-2025",
  "kategori": "Game & Interaktif",
  "karya": "https://drive.google.com/drive/folders/1FiwuyK6E2Sr3DF-VEvaQ3NUkjpWRcfje?usp=sharing",
