  "nim": "2023064",
  "judul": "PERANCANGAN GAME HORROR VISUAL NOVEL SEI LADI SEBAGAI MEDIA PENGENALAN LEGENDA URBAN KOTA BATAM KEPADA REMAJA 12-18 TAHUN",
  "semester": "Genap 2024-2025",
